literals.value:
@keyframes pulse {
          0% { transform: scale(1); opacity: 1; }
          50% { transform: scale(1.25); opacity: 0.8; }
          100% { transform: scale(1); opacity: 1; }
        }

@keyframes tilePulse {
          0%, 100% {
            transform: translate(-50%, -50%) scale(1);
            opacity: 0.6;
          }
          50% {
            transform: translate(-50%, -50%) scale(1.35);
            opacity: 0.95;
          }
        }
        @keyframes screenShake {
          0%, 100% { transform: translate(0, 0); }
          20% { transform: translate(-8px, 6px); }
          40% { transform: translate(8px, -6px); }
          60% { transform: translate(-6px, -4px); }
          80% { transform: translate(6px, 4px); }
        }
        @keyframes redFlash {
          0%, 100% { opacity: 0; }
          30%, 70% { opacity: 1; }
        }

@keyframes diceButtonBreathe {
          0%, 100% {
            transform: scale(1);
            box-shadow: 0 10px 24px rgba(217, 119, 6, 0.55), inset 0 2px 6px rgba(255, 255, 255, 0.65);
          }
          50% {
            transform: scale(1.08);
            box-shadow: 0 16px 36px rgba(245, 158, 11, 0.85), inset 0 2px 8px rgba(255, 255, 255, 0.85);
          }
        }

model-viewer {
          --poster-color: transparent !important;
          --progress-bar-color: transparent !important;
          outline: none !important;
          border: none !important;
          box-shadow: none !important;
          background: transparent !important;
          -webkit-tap-highlight-color: transparent !important;
        }
        model-viewer:focus,
        model-viewer:focus-visible,
        model-viewer:active,
        model-viewer:focus-within {
          outline: none !important;
          border: none !important;
          box-shadow: none !important;
        }

.dice-cube {
          width: 68px;
          height: 68px;
          position: relative;
          transform-style: preserve-3d;
          transition: transform 0.4s cubic-bezier(0.18, 0.89, 0.32, 1.28);
        }

        .dice-ground-shadow {
          position: absolute;
          left: 50%;
          bottom: -18px;
          transform: translateX(-50%);
          width: 64px;
          height: 18px;
          border-radius: 50%;
          background: rgba(0, 0, 0, 0.45);
          filter: blur(5px);
          transition: all 0.2s ease;
        }

        /* Khi ở Footer Dock: Nhịp thở mời gọi người chơi chạm vào gieo */
        .dice-footer-dock {
          position: relative;
          animation: diceFooterPulse 2.2s ease-in-out infinite;
        }

        @keyframes diceFooterPulse {
          0%, 100% {
            transform: scale(1);
            filter: drop-shadow(0 4px 10px rgba(56, 189, 248, 0.45));
          }
          50% {
            transform: scale(1.06);
            filter: drop-shadow(0 8px 18px rgba(56, 189, 248, 0.8));
          }
        }

        /* Khi Idle trên bãi cỏ: Nổi bồng bềnh nhẹ trên bãi cỏ */
        .dice-idle-float {
          position: relative;
          animation: diceHover 2.5s ease-in-out infinite;
        }

        @keyframes diceHover {
          0%, 100% {
            transform: translateY(0px);
          }
          50% {
            transform: translateY(-8px);
          }
        }

        /* Hoạt họa bắn từ nút GIEO ở đáy bay vút lên bãi cỏ và nảy 2 nhịp */
        .dice-toss-animation {
          position: relative;
          animation: diceTossAndBounce 0.8s cubic-bezier(0.25, 1, 0.5, 1) forwards;
        }

        @keyframes diceTossAndBounce {
          0% {
            /* Xuất phát từ vị trí nút GIEO ở đáy */
            transform: translateY(480px) scale(0.65);
            opacity: 0.8;
          }
          45% {
            /* Đạt đỉnh đường bay trên cao bãi cỏ */
            transform: translateY(-90px) scale(1.15);
            opacity: 1;
          }
          70% {
            /* Tiếp đất nhịp 1 */
            transform: translateY(0px) scale(1);
          }
          85% {
            /* Nảy lên nhịp 2 */
            transform: translateY(-28px) scale(1.04);
          }
          100% {
            /* Nằm yên vững chãi trên bãi cỏ */
            transform: translateY(0px) scale(1);
          }
        }

        /* Xoay lộn 3 trục X, Y, Z tít mù khi bay */
        .cube-tumbling {
          animation: cubeTumbleRoll 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
        }

        @keyframes cubeTumbleRoll {
          0% {
            transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg);
          }
          35% {
            transform: rotateX(540deg) rotateY(720deg) rotateZ(360deg);
          }
          70% {
            transform: rotateX(810deg) rotateY(1080deg) rotateZ(540deg);
          }
          100% {
            /* Tiếp đất mượt mà tại góc Isometric chuẩn: -30deg (690deg), -22deg (1058deg), 0deg (360deg) */
            transform: rotateX(690deg) rotateY(1058deg) rotateZ(360deg);
          }
        }

        /* Bóng đổ co giãn theo độ cao bay */
        .shadow-bounce {
          animation: shadowBounce 0.8s ease forwards;
        }

        @keyframes shadowBounce {
          0% {
            transform: translateX(-50%) scale(0.3);
            opacity: 0.1;
          }
          45% {
            transform: translateX(-50%) scale(0.5);
            opacity: 0.2;
          }
          70% {
            transform: translateX(-50%) scale(1.3);
            opacity: 0.65;
          }
          85% {
            transform: translateX(-50%) scale(0.8);
            opacity: 0.35;
          }
          100% {
            transform: translateX(-50%) scale(1);
            opacity: 0.5;
          }
        }

        @keyframes popBadge {
          from {
            transform: translateX(-50%) scale(0.5);
            opacity: 0;
          }
          to {
            transform: translateX(-50%) scale(1);
            opacity: 1;
          }
        }

@keyframes floatUpAndFade {
          0% {
            opacity: 0;
            transform: translate(-50%, -10px) scale(0.7);
          }
          20% {
            opacity: 1;
            transform: translate(-50%, -40px) scale(1.15);
          }
          70% {
            opacity: 1;
            transform: translate(-50%, -85px) scale(1);
          }
          100% {
            opacity: 0;
            transform: translate(-50%, -130px) scale(0.85);
          }
        }

@keyframes fadeIn {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
